/// The logical BLE channel for a centre frequency, for display only: `0..=36` are data channels and
/// `37`/`38`/`39` are the ADVERTISING channels (2402 / 2426 / 2480 MHz) a passive observer actually
/// watches. BLE channels sit on a 2 MHz grid from 2402 to 2480; `None` off the grid, the same
/// discipline [`channel_for`] keeps off the 802.11 grid — a frequency we cannot name is never guessed.
pub fn ble_channel_for(freq_mhz: u32) -> Option<u8> {
    if !(2402..=2480).contains(&freq_mhz) || !(freq_mhz - 2402).is_multiple_of(2) {
        return None;
    }
    let rf = ((freq_mhz - 2402) / 2) as u8; // 0..=39 in frequency order
    Some(match rf {
        0 => 37,
        12 => 38,
        39 => 39,
        1..=11 => rf - 1,  // data 0..=10
        _ => rf - 2,       // rf 13..=38 -> data 11..=36
    })
}
